
const formulario = document.getElementById("formulario");
const tabelaPessoas = document.getElementById("tabelaPessoas");
const mensagemErro = document.getElementById("mensagemErro");
const contador = document.getElementById("contador");

// Carrega os dados salvos
let pessoas = JSON.parse(localStorage.getItem("pessoas")) || [];

// Cadastros de exemplo na primeira abertura
if (pessoas.length === 0) {
    pessoas = [
            {
                        codigo: 1,
                                    nome: "Ana Exemplo",
                                                idade: 25,
                                                            altura: 1.60,
                                                                        peso: 58,
                                                                                    imc: 22.66,
                                                                                                classificacao: "Peso normal"
                                                                                                        },
                                                                                                                {
                                                                                                                            codigo: 2,
                                                                                                                                        nome: "Bruno Exemplo",
                                                                                                                                                    idade: 32,
                                                                                                                                                                altura: 1.75,
                                                                                                                                                                            peso: 76,
                                                                                                                                                                                        imc: 24.82,
                                                                                                                                                                                                    classificacao: "Peso normal"
                                                                                                                                                                                                            },
                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                codigo: 3,
                                                                                                                                                                                                                                            nome: "Carla Exemplo",
                                                                                                                                                                                                                                                        idade: 40,
                                                                                                                                                                                                                                                                    altura: 1.68,
                                                                                                                                                                                                                                                                                peso: 70,
                                                                                                                                                                                                                                                                                            imc: 24.80,
                                                                                                                                                                                                                                                                                                        classificacao: "Peso normal"
                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                    ];

                                                                                                                                                                                                                                                                                                                        salvarPessoas();
                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                        // Calcula o IMC
                                                                                                                                                                                                                                                                                                                        function calcularIMC(peso, altura) {
                                                                                                                                                                                                                                                                                                                            return peso / (altura * altura);
                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                            // Classifica o IMC
                                                                                                                                                                                                                                                                                                                            function classificarIMC(imc) {
                                                                                                                                                                                                                                                                                                                                if (imc < 18.5) {
                                                                                                                                                                                                                                                                                                                                        return "Abaixo do peso";
                                                                                                                                                                                                                                                                                                                                            } else if (imc < 25) {
                                                                                                                                                                                                                                                                                                                                                    return "Peso normal";
                                                                                                                                                                                                                                                                                                                                                        } else if (imc < 30) {
                                                                                                                                                                                                                                                                                                                                                                return "Sobrepeso";
                                                                                                                                                                                                                                                                                                                                                                    } else if (imc < 35) {
                                                                                                                                                                                                                                                                                                                                                                            return "Obesidade I";
                                                                                                                                                                                                                                                                                                                                                                                } else if (imc < 40) {
                                                                                                                                                                                                                                                                                                                                                                                        return "Obesidade II";
                                                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                                                    return "Obesidade III";
                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                        // Formata altura
                                                                                                                                                                                                                                                                                                                                                                                                        function formatarAltura(altura) {
                                                                                                                                                                                                                                                                                                                                                                                                            return altura.toFixed(2) + " m";
                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                            // Formata peso
                                                                                                                                                                                                                                                                                                                                                                                                            function formatarPeso(peso) {
                                                                                                                                                                                                                                                                                                                                                                                                                return peso.toFixed(1) + " kg";
                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                // Captura os dados do formulário
                                                                                                                                                                                                                                                                                                                                                                                                                function lerDadosFormulario() {
                                                                                                                                                                                                                                                                                                                                                                                                                    return {
                                                                                                                                                                                                                                                                                                                                                                                                                            nome: document.getElementById("nome").value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                    idade: Number(document.getElementById("idade").value),
                                                                                                                                                                                                                                                                                                                                                                                                                                            altura: Number(document.getElementById("altura").value),
                                                                                                                                                                                                                                                                                                                                                                                                                                                    peso: Number(document.getElementById("peso").value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                        };
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Valida os dados
                                                                                                                                                                                                                                                                                                                                                                                                                                                        function validarDados(pessoa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (pessoa.nome === "") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarErro("Digite o nome.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (pessoa.idade <= 0 || pessoa.idade > 120) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarErro("Digite uma idade válida.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (pessoa.altura <= 0 || pessoa.altura > 2.5) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarErro("Digite uma altura válida.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (pessoa.peso <= 0 || pessoa.peso > 500) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarErro("Digite um peso válido.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            limparErro();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Mostra mensagem de erro
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function mostrarErro(mensagem) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mensagemErro.textContent = mensagem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Limpa mensagem de erro
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function limparErro() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mensagemErro.textContent = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Adiciona uma pessoa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function adicionarPessoa(dados) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const imc = calcularIMC(dados.peso, dados.altura);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const pessoa = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        codigo: pessoas.length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ? Math.max(...pessoas.map(p => p.codigo)) + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                : 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        nome: dados.nome,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                idade: dados.idade,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        altura: dados.altura,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                peso: dados.peso,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        imc: imc,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                classificacao: classificarIMC(imc)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoas.push(pessoa);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            salvarPessoas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                renderizarTabela();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Salva no localStorage
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function salvarPessoas() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    localStorage.setItem("pessoas", JSON.stringify(pessoas));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Renderiza a tabela
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function renderizarTabela() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tabelaPessoas.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            pessoas.forEach(function(pessoa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const linha = document.createElement("tr");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const valores = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoa.codigo,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pessoa.nome,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                pessoa.idade,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            formatarAltura(pessoa.altura),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        formatarPeso(pessoa.peso),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pessoa.imc.toFixed(2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                pessoa.classificacao
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                valores.forEach(function(valor) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const coluna = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        coluna.textContent = valor;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    linha.appendChild(coluna);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const colunaAcao = document.createElement("td");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const botao = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botao.textContent = "Excluir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botao.className = "excluir";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botao.onclick = function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                excluirPessoa(pessoa.codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                colunaAcao.appendChild(botao);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        linha.appendChild(colunaAcao);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tabelaPessoas.appendChild(linha);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        contador.textContent = pessoas.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Exclui uma pessoa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function excluirPessoa(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            pessoas = pessoas.filter(function(pessoa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return pessoa.codigo !== codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            salvarPessoas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                renderizarTabela();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Evento de envio
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                formulario.addEventListener("submit", function(event) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    event.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const dados = lerDadosFormulario();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!validarDados(dados)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            adicionarPessoa(dados);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                formulario.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    limparErro();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Carrega as pessoas
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function carregarPessoas() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        renderizarTabela();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Inicializa o projeto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        carregarPessoas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        